input.old_string:
case "${2:-all}" in
  qemu)     clean_qemu ;;
  vsim)     clean_vsim ;;
  plugin)   clean_plugin ;;
  simpoint) clean_simpoint ;;
  all)      clean_qemu; clean_vsim; clean_plugin; clean_simpoint ;;
  *)        err "usage: source $_SETUP_SRC clean [qemu|vsim|plugin|simpoint|all]"; return 1 ;;
esac

input.new_string:
case "${2:-all}" in
  vsim)     clean_vsim ;;
  plugin)   clean_plugin ;;
  simpoint) clean_simpoint ;;
  all)      clean_vsim; clean_plugin; clean_simpoint ;;
  *)        err "usage: source $_SETUP_SRC clean [vsim|plugin|simpoint|all]"; return 1 ;;
esac
